const TOptional<double> Quantity = Tier == ScanTier::Assay
    ? TOptional<double>(Resource.AmountTonnes)
    : TOptional<double>();
Scan.Readings.Add({Rock->GetContactId(), Distance,
    Resource.Mineral, Quantity});
if (Quantity && *Quantity > UE_SMALL_NUMBER)
    Scan.Status = BeltStatus::HasOre;
